"""DAG definition, validation and shared helpers for flowd.

A workflow is a named DAG of steps; every step is a mapping::

    {"id": "build", "depends_on": ["fetch"], "max_attempts": 3}

Validation rejects duplicate ids, empty ids, unknown dependencies,
self/cyclic dependencies and bad ``max_attempts`` values.  Each step may
also declare a ``trigger_rule`` — ``all_success`` (the default when the
field is omitted), ``all_done`` or ``any_success`` — governing which
dependency outcomes unlock it; any other value (including an explicit
``null``) is rejected with ``bad_trigger_rule``.  A validated plan
is returned topologically sorted (ties broken by step id) so scheduling
order is deterministic.
"""

import heapq
import time as _time

STEP_STATES = ("pending", "ready", "running", "waiting", "succeeded", "failed", "cancelled",
               "skipped")
RUN_STATES = ("pending", "running", "succeeded", "failed", "cancelled")
DEFAULT_MAX_ATTEMPTS = 3

KIND_TASK = "task"
KIND_APPROVAL = "approval"
STEP_KINDS = (KIND_TASK, KIND_APPROVAL)

TRIGGER_ALL_SUCCESS = "all_success"
TRIGGER_ALL_DONE = "all_done"
TRIGGER_ANY_SUCCESS = "any_success"
TRIGGER_RULES = (TRIGGER_ALL_SUCCESS, TRIGGER_ALL_DONE, TRIGGER_ANY_SUCCESS)


class WorkflowError(Exception):
    """Raised for any rejected workflow definition or illegal call."""

    def __init__(self, message, code="invalid_workflow"):
        super().__init__(message)
        self.code = code
        self.message = message


def format_time(seconds):
    """Render epoch ``seconds`` as a sortable UTC ISO-8601 timestamp."""
    whole = int(seconds)
    micros = int(round((seconds - whole) * 1000000))
    if micros >= 1000000:
        whole, micros = whole + 1, micros - 1000000
    return "%s.%06dZ" % (_time.strftime("%Y-%m-%dT%H:%M:%S", _time.gmtime(whole)), micros)


def validate_step(raw, index, seen_ids):
    """Validate one step definition and return its normalized form."""
    if not isinstance(raw, dict):
        raise WorkflowError("step %d must be an object" % index)
    step_id = raw.get("id")
    if not isinstance(step_id, str):
        raise WorkflowError("step %d is missing a string id" % index)
    step_id = step_id.strip()
    if not step_id:
        raise WorkflowError("step %d has an empty id" % index)
    if step_id in seen_ids:
        raise WorkflowError("duplicate step id: %s" % step_id, "duplicate_step")
    seen_ids.add(step_id)
    depends_on = raw.get("depends_on") or []
    if not isinstance(depends_on, list):
        raise WorkflowError("step %s: depends_on must be a list" % step_id)
    for dep in depends_on:
        if not isinstance(dep, str) or not dep.strip():
            raise WorkflowError("step %s: depends_on entries must be non-empty strings" % step_id)
    depends_on = [d.strip() for d in depends_on]
    if len(set(depends_on)) != len(depends_on):
        raise WorkflowError("step %s: duplicate dependencies" % step_id)
    if step_id in depends_on:
        raise WorkflowError("step %s depends on itself" % step_id, "self_dependency")
    max_attempts = raw.get("max_attempts")
    if max_attempts is None:
        max_attempts = DEFAULT_MAX_ATTEMPTS
    if isinstance(max_attempts, bool) or not isinstance(max_attempts, int):
        raise WorkflowError("step %s: max_attempts must be an integer" % step_id, "bad_max_attempts")
    if max_attempts < 1:
        raise WorkflowError("step %s: max_attempts must be >= 1" % step_id, "bad_max_attempts")
    kind = raw.get("kind")
    if kind is None:
        kind = KIND_TASK
    if not isinstance(kind, str) or kind not in STEP_KINDS:
        raise WorkflowError(
            "step %s: kind must be one of %s" % (step_id, ", ".join(STEP_KINDS)), "bad_kind"
        )
    if "trigger_rule" in raw:
        trigger_rule = raw["trigger_rule"]
        if not isinstance(trigger_rule, str) or trigger_rule not in TRIGGER_RULES:
            raise WorkflowError(
                "step %s: trigger_rule must be one of %s"
                % (step_id, ", ".join(TRIGGER_RULES)),
                "bad_trigger_rule",
            )
    else:
        # Omitted means the legacy rule: unlock only when all dependencies
        # succeeded.  An explicit null is rejected like any other bad value.
        trigger_rule = TRIGGER_ALL_SUCCESS
    return {"id": step_id, "depends_on": depends_on, "max_attempts": max_attempts,
            "kind": kind, "trigger_rule": trigger_rule}


def topo_order(steps):
    """Return step ids in dependency order using Kahn's algorithm."""
    ids = [s["id"] for s in steps]
    children = {sid: [] for sid in ids}
    indegree = {}
    for step in steps:
        for dep in step["depends_on"]:
            children[dep].append(step["id"])
        indegree[step["id"]] = len(step["depends_on"])
    heap = [(sid, sid) for sid in ids if indegree[sid] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        _, sid = heapq.heappop(heap)
        order.append(sid)
        for child in sorted(children[sid]):
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(heap, (child, child))
    if len(order) != len(ids):
        raise WorkflowError(
            "cyclic dependency involving: %s" % ", ".join(sorted(set(ids) - set(order))), "cycle"
        )
    return order


def plan_workflow(workflow_id, steps):
    """Validate ``steps`` and return a normalized, topologically sorted plan."""
    if not isinstance(workflow_id, str) or not workflow_id.strip():
        raise WorkflowError("workflow_id must be a non-empty string")
    if not isinstance(steps, list) or not steps:
        raise WorkflowError("steps must be a non-empty list")
    seen = set()
    normalized = [validate_step(raw, i, seen) for i, raw in enumerate(steps)]
    for step in normalized:
        for dep in step["depends_on"]:
            if dep not in seen:
                raise WorkflowError(
                    "step %s depends on unknown step: %s" % (step["id"], dep), "unknown_dependency"
                )
    order = topo_order(normalized)
    index = {sid: i for i, sid in enumerate(order)}
    return {
        "workflow_id": workflow_id.strip(),
        "steps": sorted(normalized, key=lambda s: index[s["id"]]),
        "order": order,
    }

"""Scheduling engine: run state machine, leases, retries, history, replay.

All state transitions funnel through :class:`Scheduler` so the append-only
history stays the single source of truth.  ``replay`` rebuilds current state
from that history and must agree with the stored document.
"""

import copy
import math
import time as _time

from .model import (
    KIND_APPROVAL,
    KIND_TASK,
    TRIGGER_ALL_DONE,
    TRIGGER_ALL_SUCCESS,
    TRIGGER_ANY_SUCCESS,
    WorkflowError,
    format_time,
)
from .store import (
    RUN_CANCELLED,
    RUN_FAILED,
    RUN_PENDING,
    RUN_RUNNING,
    RUN_SUCCEEDED,
    STEP_CANCELLED,
    STEP_FAILED,
    STEP_PENDING,
    STEP_READY,
    STEP_RUNNING,
    STEP_SKIPPED,
    STEP_SUCCEEDED,
    STEP_WAITING,
    TERMINAL_RUN_STATES,
    TERMINAL_STEP_STATES,
    WorkflowStore,
    new_run,
    run_plan,
)


class LeaseError(WorkflowError):
    """Raised when a worker does not hold the lease it is acting on."""

    def __init__(self, message, code="lease_not_held"):
        super().__init__(message, code)


class ConflictError(WorkflowError):
    """Raised for an action that is incompatible with the step's state."""

    def __init__(self, message, code="conflict"):
        super().__init__(message, code)


WORKER_ACTIVE = "active"
WORKER_EXPIRED = "expired"
DEFAULT_WORKER_LEASE = 30


def backoff_seconds(attempt, base=1.0):
    """Exponential backoff: ``base * 2 ** (attempt - 1)``."""
    return float(base) * (2 ** (max(1, int(attempt)) - 1))


def normalize_max_parallelism(value):
    """Validate an optional per-run concurrency quota.

    ``None`` means unlimited; only positive integers are accepted (booleans,
    floats, strings and non-positive integers are rejected).
    """
    if value is None:
        return None
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        raise WorkflowError(
            "max_parallelism must be a positive integer or null", "bad_max_parallelism"
        )
    return int(value)


def normalize_idempotency_key(value):
    """Validate an optional idempotency key.

    ``None`` means idempotency is disabled and the call keeps its legacy
    behavior.  Otherwise the value must be a string that is non-empty after
    trimming; the trimmed key is what gets stored and matched.
    """
    if value is None:
        return None
    if not isinstance(value, str):
        raise WorkflowError("idempotency_key must be a string", "bad_idempotency_key")
    key = value.strip()
    if not key:
        raise WorkflowError("idempotency_key must be a non-empty string", "bad_idempotency_key")
    return key


def normalize_tenant(value):
    """Validate a tenant: a string that is non-empty after trimming."""
    if not isinstance(value, str):
        raise WorkflowError("tenant must be a string", "bad_tenant")
    tenant = value.strip()
    if not tenant:
        raise WorkflowError("tenant must be a non-empty string", "bad_tenant")
    return tenant


def normalize_worker_id(value):
    """Validate a worker id: a string that is non-empty after trimming."""
    if not isinstance(value, str):
        raise WorkflowError("worker_id must be a string", "bad_worker")
    worker_id = value.strip()
    if not worker_id:
        raise WorkflowError("worker_id must be a non-empty string", "bad_worker")
    return worker_id


def normalize_worker_lease(value):
    """Validate an optional worker-registration lease in seconds.

    ``None`` (omitted) defaults to 30 seconds.  Otherwise the value must be
    a finite number strictly greater than zero; booleans, strings, NaN and
    infinities are rejected.
    """
    if value is None:
        return float(DEFAULT_WORKER_LEASE)
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise WorkflowError("lease_seconds must be a positive number", "bad_lease")
    try:
        seconds = float(value)
    except OverflowError:
        seconds = float("inf")
    if not math.isfinite(seconds) or seconds <= 0:
        raise WorkflowError("lease_seconds must be a positive number", "bad_lease")
    return seconds


def normalize_params(value):
    """Validate ``params`` on a keyed create: object only, null/omit = ``{}``."""
    if value is None:
        return {}
    if not isinstance(value, dict):
        raise WorkflowError("params must be a JSON object", "bad_params")
    return value


def normalize_schedule_id(value):
    """Validate a schedule id: a string that is non-empty after trimming."""
    if not isinstance(value, str):
        raise WorkflowError("schedule_id must be a string", "bad_schedule_id")
    schedule_id = value.strip()
    if not schedule_id:
        raise WorkflowError("schedule_id must be a non-empty string", "bad_schedule_id")
    return schedule_id


def normalize_interval_seconds(value):
    """Validate a schedule interval.

    The value must be a finite number strictly greater than zero; booleans,
    strings, ``NaN`` and infinities are rejected.
    """
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise WorkflowError("interval_seconds must be a finite positive number",
                            "bad_interval")
    try:
        seconds = float(value)
    except OverflowError:
        seconds = float("inf")
    if not math.isfinite(seconds) or seconds <= 0:
        raise WorkflowError("interval_seconds must be a finite positive number",
                            "bad_interval")
    return seconds


def normalize_first_at(value):
    """Validate an optional schedule first-fire time in UTC Unix seconds.

    ``None`` (omitted or explicit ``null``) means the creation time and is
    filled in by the caller.  Otherwise the value must be a finite,
    non-negative int or float (booleans, strings, NaN and infinities are
    rejected).
    """
    if value is None:
        return None
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise WorkflowError(
            "first_at must be a finite non-negative number of Unix seconds or null",
            "bad_first_at",
        )
    try:
        seconds = float(value)
    except OverflowError:
        seconds = float("inf")
    if not math.isfinite(seconds) or seconds < 0:
        raise WorkflowError(
            "first_at must be a finite non-negative number of Unix seconds or null",
            "bad_first_at",
        )
    return seconds


def normalize_schedule_params(value):
    """Validate ``params`` on a schedule: object only, null/omit = ``{}``."""
    if value is None:
        return {}
    if not isinstance(value, dict):
        raise WorkflowError("params must be a JSON object", "bad_params")
    return value


def normalize_not_before(value):
    """Validate an optional delayed-start time in UTC Unix seconds.

    ``None`` (omitted or explicit ``null``) means start immediately.
    Otherwise the value must be a finite, non-negative int or float
    (booleans, strings, NaN and infinities are rejected).
    """
    if value is None:
        return None
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise WorkflowError(
            "not_before must be a finite non-negative number of Unix seconds or null",
            "bad_not_before",
        )
    try:
        seconds = float(value)
    except OverflowError:
        seconds = float("inf")
    if not math.isfinite(seconds) or seconds < 0:
        raise WorkflowError(
            "not_before must be a finite non-negative number of Unix seconds or null",
            "bad_not_before",
        )
    return seconds


def params_equal(left, right):
    """Semantic JSON equality for run params.

    Object key order is ignored, array order is preserved, booleans are not
    numbers (``True != 1``), and numeric ints/floats compare by numeric value
    (``1 == 1.0``).
    """
    if isinstance(left, bool) or isinstance(right, bool):
        return isinstance(left, bool) and isinstance(right, bool) and left == right
    if isinstance(left, dict) or isinstance(right, dict):
        if not (isinstance(left, dict) and isinstance(right, dict)):
            return False
        if left.keys() != right.keys():
            return False
        return all(params_equal(left[name], right[name]) for name in left)
    if isinstance(left, list) or isinstance(right, list):
        if not (isinstance(left, list) and isinstance(right, list)):
            return False
        return len(left) == len(right) and all(
            params_equal(a, b) for a, b in zip(left, right)
        )
    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        return left == right
    return left == right


def _retry_due(step, now_iso):
    """Whether a ready step's backoff has elapsed (or it never failed).

    ``next_attempt_at`` is set when a failure re-queues the step with
    remaining attempts; the step becomes claimable again only once the
    current time reaches that moment.  Both timestamps come from
    :func:`format_time`, so lexicographic comparison is chronological.
    """
    next_attempt_at = step.get("next_attempt_at")
    return next_attempt_at is None or next_attempt_at <= now_iso


def _active_lease_count(run, now):
    """Count ordinary tasks in this run holding a strictly unexpired lease.

    Approval nodes and tasks that are ready, waiting, succeeded, failed or
    pending retry do not count; a deadline equal to ``now`` is expired.
    Each held task counts once, even when one worker holds several.
    """
    return sum(
        1
        for step in run["steps"].values()
        if step.get("kind") != KIND_APPROVAL
        and step["status"] == STEP_RUNNING
        and step.get("lease_deadline") is not None
        and float(step["lease_deadline"]) > now
    )


def _run_has_custom_trigger(run):
    """Whether any node of the run unlocks by a rule other than all_success.

    The rule is frozen into every node at creation; runs written before
    trigger rules existed read back as pure ``all_success`` runs.
    """
    return any(
        step.get("trigger_rule", TRIGGER_ALL_SUCCESS) != TRIGGER_ALL_SUCCESS
        for step in run["steps"].values()
    )


def _promote_pending(run, now_iso):
    """Unlock or skip pending steps whose dependencies are settled.

    Every pending node is evaluated in topological order against the
    ``trigger_rule`` frozen into it at creation:

    - ``all_success`` unlocks when every dependency succeeded.  Once a
      dependency is failed, cancelled or skipped the node can never unlock,
      so it is skipped instead — but only in runs that use custom trigger
      rules; all-``all_success`` runs keep the legacy semantics exactly
      (the run has already failed and pending nodes simply stay pending).
    - ``all_done`` unlocks once every dependency reached a terminal state
      (``succeeded``, ``failed``, ``cancelled`` or ``skipped``).
    - ``any_success`` unlocks as soon as any dependency succeeded, and is
      skipped once all dependencies are terminal without a success.

    Root nodes open immediately under every rule.  Ordinary tasks become
    ``ready``; approval steps become ``waiting`` for a human decision.
    Returns ``(step_id, new_status)`` pairs in topological order.
    """
    index = run["order_index"]
    skippable = _run_has_custom_trigger(run)
    opened = []
    for sid in sorted(run["steps"], key=lambda s: index.get(s, 0)):
        step = run["steps"][sid]
        if step["status"] != STEP_PENDING:
            continue
        deps = [run["steps"][d] for d in step["depends_on"]]
        rule = step.get("trigger_rule", TRIGGER_ALL_SUCCESS)
        skip = False
        if not deps:
            unlock = True
        elif rule == TRIGGER_ALL_DONE:
            unlock = all(d["status"] in TERMINAL_STEP_STATES for d in deps)
        elif rule == TRIGGER_ANY_SUCCESS:
            unlock = any(d["status"] == STEP_SUCCEEDED for d in deps)
            skip = not unlock and all(d["status"] in TERMINAL_STEP_STATES for d in deps)
        else:
            unlock = all(d["status"] == STEP_SUCCEEDED for d in deps)
            skip = not unlock and skippable and any(
                d["status"] in (STEP_FAILED, STEP_CANCELLED, STEP_SKIPPED) for d in deps)
        if skip:
            step["status"] = STEP_SKIPPED
            opened.append((sid, STEP_SKIPPED))
        elif unlock:
            if step.get("kind") == KIND_APPROVAL:
                step["status"] = STEP_WAITING
                opened.append((sid, STEP_WAITING))
            else:
                step["status"], step["ready_at"] = STEP_READY, now_iso
                opened.append((sid, STEP_READY))
    return opened


def _derive_run_status(run):
    """Derive the run status from its steps; stays ``pending`` until claimed.

    A run using custom trigger rules keeps going while any node can still
    be unlocked, is executing or awaits a decision, and finishes only once
    every node is terminal: ``failed`` when any node failed, otherwise
    ``succeeded`` (an explicit cancel shows up as cancelled nodes and stays
    ``cancelled``).  All-``all_success`` runs keep the legacy rule: the
    first exhausted attempt or rejection fails the run immediately.
    """
    steps = list(run["steps"].values())
    if _run_has_custom_trigger(run):
        if any(s["status"] == STEP_CANCELLED for s in steps):
            return RUN_CANCELLED
        if steps and all(s["status"] in TERMINAL_STEP_STATES for s in steps):
            if any(s["status"] == STEP_FAILED for s in steps):
                return RUN_FAILED
            return RUN_SUCCEEDED
        if any(s["status"] in (STEP_RUNNING, STEP_SUCCEEDED) for s in steps):
            return RUN_RUNNING
        return RUN_PENDING
    if any(s["status"] == STEP_FAILED for s in steps):
        return RUN_FAILED
    if any(s["status"] == STEP_CANCELLED for s in steps):
        return RUN_CANCELLED
    if steps and all(s["status"] == STEP_SUCCEEDED for s in steps):
        return RUN_SUCCEEDED
    if any(s["status"] in (STEP_RUNNING, STEP_SUCCEEDED) for s in steps):
        return RUN_RUNNING
    return RUN_PENDING


def _roots_opened(run):
    """Whether the run's root nodes were already opened (activation done).

    A sleeping (delayed) run has exactly one history event, ``run_created``;
    activation appends one ``ready``/``waiting`` event per root node, and a
    validated workflow always has at least one root.
    """
    return any(e.get("type") in ("ready", "waiting") for e in run.get("history") or [])


class Scheduler:
    """Coordinates workers against a :class:`WorkflowStore`."""

    def __init__(self, store, clock=None, backoff_base=1.0, sleep=None):
        self.store = store
        self._clock = clock if clock is not None else store.now
        self.backoff_base = float(backoff_base)
        self._sleep = sleep if sleep is not None else _time.sleep

    def now(self):
        return float(self._clock())

    def _iso(self, when=None):
        return format_time(self.now() if when is None else when)

    def _event(self, run, run_id, step_id, etype, attempt=None, worker_id=None, **extra):
        event = {"at": self._iso(), "run_id": run_id, "step_id": step_id, "type": etype,
                 "attempt": attempt, "worker_id": worker_id}
        event.update(extra)
        run["history"].append(event)
        # Every persisted history event is also an audit record: run actions
        # keep their history type as the audit action and enter the tenant
        # stream in the order the changes actually happened.
        self.store.append_audit(run["tenant"], etype, at=event["at"], run_id=run_id,
                                step_id=step_id, workflow_id=run.get("workflow_id"),
                                worker_id=worker_id, actor=extra.get("actor"))
        return event

    # -- workflow / run lifecycle --------------------------------------
    def submit(self, tenant, workflow_id, steps):
        with self.store.locked():
            plan = self.store.save_workflow(tenant, workflow_id, steps)
            self.store.append_audit(tenant, "workflow.submit",
                                    workflow_id=plan["workflow_id"])
            return plan

    def start_run(self, tenant, workflow_id, run_id=None, params=None, max_parallelism=None,
                  idempotency_key=None, not_before=None, schedule_id=None, scheduled_at=None):
        key = normalize_idempotency_key(idempotency_key)
        max_parallelism = normalize_max_parallelism(max_parallelism)
        if key is not None:
            params = normalize_params(params)
        not_before = normalize_not_before(not_before)
        with self.store.locked():
            if key is not None:
                return self._start_idempotent_run(
                    tenant, workflow_id, run_id, params, max_parallelism, key, not_before,
                    schedule_id, scheduled_at
                )
            plan = self.store.get_workflow(tenant, workflow_id)
            run_id = run_id or self.store.generate_run_id()
            if self.store.run_exists(run_id) == tenant:
                raise WorkflowError("run already exists: %s" % run_id, "duplicate_run")
            run = new_run(tenant, workflow_id, run_id, params, plan, self._iso(),
                          max_parallelism=max_parallelism, not_before=not_before,
                          schedule_id=schedule_id, scheduled_at=scheduled_at)
            return self._create_run(run, plan)

    def _start_idempotent_run(self, tenant, workflow_id, run_id, params, max_parallelism, key,
                              not_before, schedule_id=None, scheduled_at=None):
        """Create once per (tenant, trimmed key); replay identical requests.

        Runs inside the store lock so concurrent identical requests share one
        run while differing requests conflict against the first creation.
        """
        index = self.store.load_idempotency(tenant)
        record = index.get(key)
        if record is not None:
            existing = self.get_run(tenant, record["run_id"])
            if run_id is not None and run_id != existing["run_id"]:
                raise ConflictError(
                    "idempotency_key %s is already bound to run %s"
                    % (key, existing["run_id"]),
                    "idempotency_conflict",
                )
            if existing["workflow_id"] != workflow_id \
                    or not params_equal(existing.get("params") or {}, params) \
                    or existing.get("max_parallelism") != max_parallelism \
                    or existing.get("not_before") != not_before:
                raise ConflictError(
                    "request differs from the run first created with idempotency_key %s" % key,
                    "idempotency_conflict",
                )
            # A repeat changes nothing: no history, no updated_at, no lease.
            return existing
        plan = self.store.get_workflow(tenant, workflow_id)
        run_id = run_id or self.store.generate_run_id()
        if self.store.run_exists(run_id) == tenant:
            raise WorkflowError("run already exists: %s" % run_id, "duplicate_run")
        run = new_run(tenant, workflow_id, run_id, params, plan, self._iso(),
                      max_parallelism=max_parallelism, idempotency_key=key,
                      not_before=not_before, schedule_id=schedule_id,
                      scheduled_at=scheduled_at)
        self._create_run(run, plan)
        index[key] = {"run_id": run_id}
        self.store.save_idempotency(tenant, index)
        return run

    def _create_run(self, run, plan):
        """Append creation events and persist a freshly built run.

        A run with a future ``not_before`` stays fully ``pending``: its root
        nodes are opened (one ``ready``/``waiting`` history event each) only
        when the first claim arrives at or after that time.  A past, present
        or missing start time opens the roots immediately, exactly like the
        legacy create behavior.
        """
        run_id = run["run_id"]
        self._event(run, run_id, None, "run_created")
        not_before = run.get("not_before")
        if not_before is None or float(not_before) <= self.now():
            self._open_root_nodes(run)
        run["status"], run["updated_at"] = _derive_run_status(run), self._iso()
        return self.store.save_run(run)

    def _open_root_nodes(self, run, when=None):
        """Settle every pending node whose dependencies are decided.

        Each unlocked or skipped node records exactly one ``ready``,
        ``waiting`` or ``skipped`` history event, emitted in topological
        order, so calling this on repeated claims never re-opens a node.
        Returns the ``(step_id, new_status)`` transitions.
        """
        now_iso = self._iso() if when is None else when
        opened = _promote_pending(run, now_iso)
        for sid, status in opened:
            attempt = 0 if status == STEP_WAITING else run["steps"][sid]["attempt"]
            self._event(run, run["run_id"], sid, status, attempt=attempt)
        return opened

    def get_run(self, tenant, run_id):
        run = self.store.load_run(tenant, run_id)
        if run["tenant"] != tenant:
            raise WorkflowError("run %s belongs to another tenant" % run_id, "cross_tenant")
        return run

    def list_runs(self, tenant, status=None, limit=50, after=None):
        return self.store.list_runs(tenant, status=status, limit=limit, after=after)

    # -- tenant concurrency quota ---------------------------------------
    def set_quota(self, tenant, max_parallelism=None):
        """Create or update the tenant's concurrency quota.

        ``max_parallelism`` omitted or ``None`` means unlimited; otherwise it
        must be a positive integer.  Returns ``(record, created)`` where
        ``created`` is ``True`` for the first write (HTTP 201) and ``False``
        for a later update (HTTP 200).  Rewriting the same value changes
        nothing: ``updated_at`` is kept and no audit record is appended; a
        real change appends one ``quota.set`` audit record.
        """
        tenant = normalize_tenant(tenant)
        quota = normalize_max_parallelism(max_parallelism)
        with self.store.locked():
            existing = self.store.load_quota(tenant)
            if existing is not None and existing.get("max_parallelism") == quota:
                return dict(existing), False
            record = {"tenant": tenant, "max_parallelism": quota,
                      "updated_at": self._iso()}
            self.store.save_quota(tenant, record)
            self.store.append_audit(tenant, "quota.set")
            return dict(record), existing is None

    def get_quota(self, tenant):
        """Read the tenant's quota; unconfigured tenants report ``None``.

        Read-only: never writes state and never appends audit records.  A
        tenant only ever reads the record stored under its own directory.
        """
        tenant = normalize_tenant(tenant)
        with self.store.locked():
            record = self.store.load_quota(tenant)
        if record is None:
            return {"tenant": tenant, "max_parallelism": None, "updated_at": None}
        return dict(record)

    def _tenant_quota_limit(self, tenant):
        """The tenant's active lease budget, or ``None`` when unlimited."""
        record = self.store.load_quota(tenant)
        if record is None:
            return None
        return record.get("max_parallelism")

    def _reclaim_tenant_leases(self, runs, now):
        """Expire overdue leases in every given run of a tenant.

        Each expired lease records the usual ``takeover`` history event and
        audit record; every run that changed is persisted immediately.
        """
        for run in runs:
            if self._expire_leases(run, now):
                run["status"] = _derive_run_status(run)
                run["updated_at"] = self._iso()
                self.store.save_run(run)

    # -- audit stream ---------------------------------------------------
    def list_audit(self, tenant, action=None, run_id=None, limit=100, after=0):
        """Read the tenant's audit stream; never mutates any state.

        Returns ``(items, next_after)`` where ``items`` are the tenant's
        audit records with ``sequence > after`` (optionally filtered by
        ``action`` and/or ``run_id``) in ascending sequence order, at most
        ``limit`` of them, and ``next_after`` is the sequence of the last
        record of the page, or ``None`` when no further records follow.
        Only the requesting tenant's own stream is ever read.
        """
        tenant = normalize_tenant(tenant)
        if action is not None:
            if not isinstance(action, str) or not action.strip():
                raise WorkflowError("action must be a non-empty string", "bad_action")
            action = action.strip()
        if run_id is not None:
            if not isinstance(run_id, str) or not run_id.strip():
                raise WorkflowError("run_id must be a non-empty string", "bad_run_id")
            run_id = run_id.strip()
        if isinstance(limit, bool) or not isinstance(limit, int) or not 1 <= limit <= 1000:
            raise WorkflowError("limit must be an integer between 1 and 1000", "bad_limit")
        if isinstance(after, bool) or not isinstance(after, int) or after < 0:
            raise WorkflowError("after must be a non-negative integer", "bad_after")
        with self.store.locked():
            matched = [r for r in self.store.load_audit(tenant) if r["sequence"] > after]
        if action is not None:
            matched = [r for r in matched if r["action"] == action]
        if run_id is not None:
            matched = [r for r in matched if r.get("run_id") == run_id]
        matched.sort(key=lambda r: r["sequence"])
        page = matched[:limit]
        next_after = page[-1]["sequence"] if len(matched) > limit else None
        return page, next_after

    def history(self, run_id, tenant=None):
        if tenant is None:
            tenant = self.store.run_exists(run_id)
            if tenant is None:
                raise WorkflowError("unknown run: %s" % run_id, "unknown_run")
        return list(self.get_run(tenant, run_id)["history"])

    # -- periodic schedules -------------------------------------------
    def create_schedule(self, tenant, schedule_id, workflow_id, interval_seconds,
                        first_at=None, params=None, max_parallelism=None):
        """Create a persistent periodic schedule for one tenant.

        ``first_at`` omitted (or ``null``) defaults to the current time.
        Returns the stored record; a duplicate id within the same tenant
        conflicts (``schedule_exists``).
        """
        tenant = normalize_tenant(tenant)
        schedule_id = normalize_schedule_id(schedule_id)
        interval = normalize_interval_seconds(interval_seconds)
        first_at = normalize_first_at(first_at)
        params = normalize_schedule_params(params)
        max_parallelism = normalize_max_parallelism(max_parallelism)
        with self.store.locked():
            schedules = self.store.load_schedules(tenant)
            if schedule_id in schedules:
                raise ConflictError(
                    "schedule already exists: %s" % schedule_id, "schedule_exists"
                )
            plan = self.store.get_workflow(tenant, workflow_id)
            now = self.now()
            next_at = now if first_at is None else first_at
            record = {
                "tenant": tenant,
                "schedule_id": schedule_id,
                "workflow_id": plan["workflow_id"],
                "interval_seconds": interval,
                "first_at": next_at,
                "next_at": next_at,
                "params": params,
                "max_parallelism": max_parallelism,
                "created_at": self._iso(now),
                "updated_at": self._iso(now),
            }
            schedules[schedule_id] = record
            self.store.save_schedules(tenant, schedules)
            self.store.append_audit(tenant, "schedule.create", schedule_id=schedule_id,
                                    workflow_id=plan["workflow_id"])
            return dict(record)

    def list_schedules(self, tenant):
        """Return the tenant's schedules sorted by schedule_id."""
        tenant = normalize_tenant(tenant)
        with self.store.locked():
            schedules = self.store.load_schedules(tenant)
            return [dict(schedules[sid]) for sid in sorted(schedules)]

    def dispatch_schedule(self, tenant, schedule_id):
        """Fire a schedule when due.

        Returns ``(run, scheduled_at)`` when a run was created, or
        ``(None, None)`` when the schedule is not yet due (HTTP 204).  Only
        the single due trigger point is processed per call: ``next_at``
        advances by exactly one interval, so a repeat before the next
        trigger is due changes nothing and missed trigger points are caught
        up one per call in chronological order.
        """
        tenant = normalize_tenant(tenant)
        schedule_id = normalize_schedule_id(schedule_id)
        now = self.now()
        with self.store.locked():
            owner = self.store.schedule_exists(schedule_id)
            if owner is None:
                raise WorkflowError(
                    "unknown schedule: %s" % schedule_id, "unknown_schedule"
                )
            if owner != tenant:
                raise WorkflowError(
                    "schedule %s belongs to another tenant" % schedule_id, "cross_tenant"
                )
            schedules = self.store.load_schedules(tenant)
            record = schedules[schedule_id]
            scheduled_at = float(record["next_at"])
            if now < scheduled_at:
                return None, None
            run = self.start_run(
                tenant,
                record["workflow_id"],
                params=record.get("params") or {},
                max_parallelism=record.get("max_parallelism"),
                schedule_id=schedule_id,
                scheduled_at=scheduled_at,
            )
            record["next_at"] = scheduled_at + float(record["interval_seconds"])
            record["updated_at"] = self._iso(now)
            schedules[schedule_id] = record
            self.store.save_schedules(tenant, schedules)
            self.store.append_audit(tenant, "schedule.dispatch", schedule_id=schedule_id,
                                    run_id=run["run_id"])
            return run, scheduled_at

    # -- worker registry -----------------------------------------------
    def _worker_view(self, record, now=None):
        """Project a stored registration record with live status."""
        now = self.now() if now is None else now
        deadline = float(record["expires_at_epoch"])
        return {
            "worker_id": record["worker_id"],
            "status": WORKER_ACTIVE if now < deadline else WORKER_EXPIRED,
            "registered_at": record["registered_at"],
            "last_heartbeat": record["last_heartbeat"],
            "expires_at": record["expires_at"],
        }

    def register_worker(self, tenant, worker_id, lease_seconds=None):
        """Register ``worker_id`` for ``tenant`` (or refresh its expiry).

        Returns ``(record, created)`` where ``created`` is ``True`` for the
        first registration (HTTP 201) and ``False`` for a repeat that
        refreshed an existing record (HTTP 200).  Registration never writes
        run history.
        """
        tenant = normalize_tenant(tenant)
        worker_id = normalize_worker_id(worker_id)
        lease = normalize_worker_lease(lease_seconds)
        now = self.now()
        with self.store.locked():
            workers = self.store.load_workers(tenant)
            existing = workers.get(worker_id)
            deadline = now + lease
            at = self._iso(now)
            if existing is None:
                record = {
                    "worker_id": worker_id,
                    "registered_at": at,
                    "last_heartbeat": at,
                    "expires_at": self._iso(deadline),
                    "expires_at_epoch": deadline,
                }
                created = True
            else:
                # A repeat registration simply refreshes the expiry; the
                # original registered_at is preserved.
                record = dict(existing)
                record.update(last_heartbeat=at, expires_at=self._iso(deadline),
                              expires_at_epoch=deadline)
                created = False
            workers[worker_id] = record
            self.store.save_workers(tenant, workers)
            self.store.append_audit(tenant, "worker.register", worker_id=worker_id)
            return self._worker_view(record, now), created

    def heartbeat_worker(self, tenant, worker_id, lease_seconds=None):
        """Heartbeat a registered worker.

        The new expiry is the later of the old one and ``now +
        lease_seconds``.  Unknown workers raise ``unknown_worker`` (404) and
        workers whose registration has expired raise ``worker_expired``
        (409); an expired worker must re-register.
        """
        tenant = normalize_tenant(tenant)
        worker_id = normalize_worker_id(worker_id)
        lease = normalize_worker_lease(lease_seconds)
        now = self.now()
        with self.store.locked():
            workers = self.store.load_workers(tenant)
            record = workers.get(worker_id)
            if record is None:
                raise WorkflowError("unknown worker: %s" % worker_id, "unknown_worker")
            if now >= float(record["expires_at_epoch"]):
                raise ConflictError(
                    "worker_expired: registration of worker %s has expired; re-register"
                    % worker_id,
                    "worker_expired",
                )
            deadline = max(float(record["expires_at_epoch"]), now + lease)
            record = dict(record)
            record.update(last_heartbeat=self._iso(now), expires_at=self._iso(deadline),
                          expires_at_epoch=deadline)
            workers[worker_id] = record
            self.store.save_workers(tenant, workers)
            self.store.append_audit(tenant, "worker.heartbeat", worker_id=worker_id)
            return self._worker_view(record, now)

    def list_workers(self, tenant):
        """Return the tenant's worker records sorted by worker_id.

        Status is computed against the current time on every call, so
        expired workers are reported without any background reaper.
        """
        tenant = normalize_tenant(tenant)
        now = self.now()
        with self.store.locked():
            workers = self.store.load_workers(tenant)
            return [self._worker_view(workers[worker_id], now)
                    for worker_id in sorted(workers)]

    def _check_worker_registration(self, tenant, worker_id, now):
        """Gate claims against the tenant's worker registry.

        A tenant with no registration records keeps the legacy rule (any
        non-empty worker_id).  Once any record exists the caller must be a
        registered worker whose registration is strictly unexpired.
        """
        workers = self.store.load_workers(tenant)
        if not workers:
            return
        record = workers.get(worker_id)
        if record is None:
            raise ConflictError(
                "worker_not_registered: worker %s is not registered for tenant %s"
                % (worker_id, tenant),
                "worker_not_registered",
            )
        if now >= float(record["expires_at_epoch"]):
            raise ConflictError(
                "worker_expired: registration of worker %s has expired; re-register"
                % worker_id,
                "worker_expired",
            )

    # -- lease expiry --------------------------------------------------
    def _expire_leases(self, run, now):
        """Release leases past their deadline; each one records a takeover."""
        reclaimed = []
        for sid in sorted(run["steps"], key=lambda s: run["order_index"].get(s, 0)):
            step = run["steps"][sid]
            if step["status"] != STEP_RUNNING:
                continue
            if step.get("lease_deadline") is None or float(step["lease_deadline"]) > now:
                continue
            holder = step["worker_id"]
            step.update(status=STEP_READY, worker_id=None, lease_deadline=None, ready_at=self._iso())
            self._event(run, run["run_id"], sid, "takeover", attempt=step["attempt"], worker_id=holder)
            reclaimed.append(sid)
        return reclaimed

    # -- claim / complete / fail ---------------------------------------
    def claim(self, tenant, run_id, worker_id, lease_seconds=30):
        """Lease the next ready step, or return ``None`` when none is ready.

        A delayed run (a future ``not_before``) cannot be activated early:
        claims before the start time return ``None`` without touching its
        state, history or ``updated_at``.  The first claim at or after the
        start time opens the root nodes (one ``ready``/``waiting`` event each)
        and then leases at most one task under the usual order and quota; a
        run whose roots are all approvals activates and still returns ``None``.

        Once the tenant has any registered worker the claim must come from an
        active registration (``worker_not_registered`` / ``worker_expired``);
        a tenant with no registrations keeps the legacy non-empty-id rule.

        A ready step whose retry backoff is still pending
        (``next_attempt_at`` in the future) is not leased; other ready tasks
        whose backoff has elapsed are handed out in the usual order instead.
        When nothing is leased and no lease takeover or root activation
        happened, the run's state, history and ``updated_at`` are left
        exactly as stored.

        When the tenant has a concurrency quota configured (see
        :meth:`set_quota`), all of the tenant's runs share one active-lease
        budget: expired leases across every run are reclaimed first (with
        the usual ``takeover`` events, kept even when the budget turns out
        full), and a full budget returns ``None`` without a claim event.
        Tenants without a configured quota keep the legacy behavior exactly.
        """
        if not isinstance(worker_id, str) or not worker_id.strip():
            raise WorkflowError("worker_id must be a non-empty string", "bad_worker")
        if not isinstance(lease_seconds, (int, float)) or isinstance(lease_seconds, bool) \
                or lease_seconds <= 0:
            raise WorkflowError("lease_seconds must be a positive number", "bad_lease")
        now = self.now()
        with self.store.locked():
            owner = self.store.run_exists(run_id)
            if owner is not None and owner != tenant:
                raise WorkflowError("run %s belongs to another tenant" % run_id, "cross_tenant")
            # Once a tenant has any registered worker, claims require an
            # active registration; a tenant without records keeps the legacy
            # "any non-empty worker_id" rule.
            self._check_worker_registration(tenant, worker_id.strip(), now)
            run = self.get_run(tenant, run_id)
            not_before = run.get("not_before")
            if not_before is not None and float(not_before) > now:
                # Still sleeping: activation happens only via a due claim.
                return None
            tenant_quota = self._tenant_quota_limit(tenant)
            if tenant_quota is None:
                reclaimed = self._expire_leases(run, now)
            else:
                # A configured tenant quota shares one lease budget across
                # all of the tenant's runs: reclaim every expired lease of
                # the tenant under this lock, then count what survives.
                others = [r for r in self.store.load_all_runs(tenant)
                          if r["run_id"] != run_id]
                self._reclaim_tenant_leases(others, now)
                reclaimed = self._expire_leases(run, now)
                active = _active_lease_count(run, now) + sum(
                    _active_lease_count(other, now) for other in others)
                if active >= tenant_quota:
                    # Budget exhausted: this call's takeovers are kept, but
                    # no claim event and no other state change is added.
                    if reclaimed:
                        run["status"] = _derive_run_status(run)
                        run["updated_at"] = self._iso()
                        self.store.save_run(run)
                    return None
            opened = self._open_root_nodes(run)
            now_iso = self._iso()
            candidates = [s for s in run["steps"].values()
                          if s["status"] == STEP_READY and _retry_due(s, now_iso)]
            index = run["order_index"]
            quota = run.get("max_parallelism")
            at_quota = quota is not None and _active_lease_count(run, now) >= int(quota)
            step = (min(candidates, key=lambda s: (index.get(s["id"], 0), s["id"]))
                    if candidates and not at_quota else None)
            previous = run["status"]
            if step is not None:
                step.update(status=STEP_RUNNING, worker_id=worker_id, next_attempt_at=None,
                            lease_deadline=now + float(lease_seconds), started_at=self._iso())
                self._event(run, run_id, step["id"], "claim", attempt=step["attempt"],
                            worker_id=worker_id, lease_deadline=step["lease_deadline"])
            elif not reclaimed and not opened:
                # Nothing to lease and nothing else changed: keep the stored
                # state, history and updated_at untouched.
                return None
            run["status"] = _derive_run_status(run)
            if step is not None and run["status"] == RUN_RUNNING and previous == RUN_PENDING:
                self._event(run, run_id, None, "run_started")
            run["updated_at"] = self._iso()
            self.store.save_run(run)
            return dict(step) if step is not None else None

    def claim_fair(self, tenant, worker_id, lease_seconds=30):
        """Lease one task from the tenant's least-claimed eligible run.

        Scans every run of the tenant.  First, sleeping runs whose
        ``not_before`` has come due are activated (root nodes opened, one
        ``ready``/``waiting`` event each) in ``run_id`` order.  Then the
        candidates — runs that are not terminal, not still sleeping, hold at
        least one ``ready`` ordinary task whose retry backoff has elapsed
        (``next_attempt_at`` reached) and have not reached their
        ``max_parallelism`` — are ordered by fairness: the number of
        ``claim`` events in the run's history (fewest first), then
        ``created_at``, then ``run_id``.  A run holding only not-yet-due
        retries is skipped and its fairness count is left alone.  Expired
        leases are reclaimed with the usual ``takeover`` events before slots
        are counted, exactly like the single-run claim.  The winner leases
        its next due task in ``(topological index, step id)`` order,
        recording the usual ``claim`` and, when the run leaves ``pending``,
        ``run_started`` events.

        Returns ``(run_id, step)`` or ``None`` when no run is eligible; at
        most one task is leased per call.  The fairness count is rebuilt
        from the append-only history on every call, so restarts, replay and
        concurrent callers (serialized by the store lock) all agree.
        Worker-registration gating matches the single-run claim.

        A configured tenant concurrency quota (see :meth:`set_quota`) adds a
        shared active-lease budget across all of the tenant's runs: expired
        leases tenant-wide are reclaimed first (takeovers are kept), and a
        full budget returns ``None`` before any run is activated or leased.
        """
        tenant = normalize_tenant(tenant)
        worker_id = normalize_worker_id(worker_id)
        lease = normalize_worker_lease(lease_seconds)
        now = self.now()
        with self.store.locked():
            self._check_worker_registration(tenant, worker_id, now)
            runs = self.store.load_all_runs(tenant)
            tenant_quota = self._tenant_quota_limit(tenant)
            if tenant_quota is not None:
                # Shared tenant budget: reclaim every expired lease of the
                # tenant under this lock, then count the surviving active
                # leases.  A full budget returns nothing; the takeovers
                # recorded by the reclaim are kept.
                self._reclaim_tenant_leases(runs, now)
                if sum(_active_lease_count(run, now) for run in runs) >= tenant_quota:
                    return None
            # Activate due sleeping runs in run_id order; already-activated
            # runs are left untouched.  Terminal runs (including a cancelled
            # run whose roots were never opened) are never activated.
            for run in runs:
                if run["status"] in TERMINAL_RUN_STATES:
                    continue
                not_before = run.get("not_before")
                if not_before is None or float(not_before) > now:
                    continue
                if _roots_opened(run):
                    continue
                self._open_root_nodes(run)
                run["status"] = _derive_run_status(run)
                run["updated_at"] = self._iso()
                self.store.save_run(run)
            # Pick the fairest eligible run.
            now_iso = self._iso(now)
            best_key, best_run, best_previous = None, None, None
            for run in runs:
                if run["status"] in TERMINAL_RUN_STATES:
                    continue
                not_before = run.get("not_before")
                if not_before is not None and float(not_before) > now:
                    continue
                previous = run["status"]
                reclaimed = self._expire_leases(run, now)
                if reclaimed:
                    run["status"] = _derive_run_status(run)
                    run["updated_at"] = self._iso()
                    self.store.save_run(run)
                ready = [s for s in run["steps"].values()
                         if s["status"] == STEP_READY and _retry_due(s, now_iso)]
                if not ready:
                    continue
                quota = run.get("max_parallelism")
                if quota is not None and _active_lease_count(run, now) >= int(quota):
                    continue
                claims = sum(1 for e in run["history"] if e.get("type") == "claim")
                key = (claims, run.get("created_at") or "", run["run_id"])
                if best_key is None or key < best_key:
                    best_key, best_run, best_previous = key, run, previous
            if best_run is None:
                return None
            run = best_run
            index = run["order_index"]
            step = min((s for s in run["steps"].values()
                        if s["status"] == STEP_READY and _retry_due(s, now_iso)),
                       key=lambda s: (index.get(s["id"], 0), s["id"]))
            step.update(status=STEP_RUNNING, worker_id=worker_id, next_attempt_at=None,
                        lease_deadline=now + lease, started_at=self._iso())
            self._event(run, run["run_id"], step["id"], "claim", attempt=step["attempt"],
                        worker_id=worker_id, lease_deadline=step["lease_deadline"])
            run["status"] = _derive_run_status(run)
            if run["status"] == RUN_RUNNING and best_previous == RUN_PENDING:
                self._event(run, run["run_id"], None, "run_started")
            run["updated_at"] = self._iso()
            self.store.save_run(run)
            return run["run_id"], dict(step)

    def heartbeat(self, tenant, run_id, step_id, worker_id, lease_seconds=30):
        """Renew the lease on a running step held by ``worker_id``.

        The new deadline is the later of the current one and
        ``now + lease_seconds``; only the deadline and ``updated_at`` change.
        A renewal that would not extend the deadline returns the run
        unchanged and appends no history.
        """
        if not isinstance(worker_id, str) or not worker_id.strip():
            raise WorkflowError("worker_id must be a non-empty string", "bad_worker")
        if not isinstance(step_id, str) or not step_id.strip():
            raise WorkflowError("step_id must be a non-empty string", "bad_step")
        if not isinstance(lease_seconds, (int, float)) or isinstance(lease_seconds, bool) \
                or not math.isfinite(lease_seconds) or lease_seconds <= 0:
            raise WorkflowError("lease_seconds must be a positive number", "bad_lease")
        now = self.now()
        with self.store.locked():
            owner = self.store.run_exists(run_id)
            if owner is not None and owner != tenant:
                raise WorkflowError("run %s belongs to another tenant" % run_id, "cross_tenant")
            run = self.get_run(tenant, run_id)
            if run["status"] == RUN_CANCELLED:
                raise ConflictError("run %s is cancelled" % run_id, "run_cancelled")
            if run["status"] in (RUN_SUCCEEDED, RUN_FAILED):
                raise ConflictError("run %s is already %s" % (run_id, run["status"]),
                                    "run_finished")
            step = run["steps"].get(step_id)
            if step is None:
                raise WorkflowError("unknown step: %s" % step_id, "unknown_step")
            if step.get("kind") == KIND_APPROVAL:
                raise ConflictError(
                    "step %s is an approval node; use /decision" % step_id, "not_a_task"
                )
            if step["status"] != STEP_RUNNING:
                raise LeaseError("step %s is not running" % step_id, "lease_not_held")
            if step["worker_id"] != worker_id:
                raise LeaseError("step %s lease is not held by worker %s" % (step_id, worker_id))
            deadline = float(step["lease_deadline"])
            if now >= deadline:
                raise LeaseError("lease for step %s expired" % step_id, "lease_expired")
            new_deadline = max(deadline, now + float(lease_seconds))
            if new_deadline <= deadline:
                return run
            step["lease_deadline"] = new_deadline
            self._event(run, run_id, step_id, "heartbeat", attempt=step["attempt"],
                        worker_id=worker_id, lease_deadline=new_deadline)
            run["updated_at"] = self._iso()
            self.store.save_run(run)
            return run

    def _require_lease(self, run, step_id, worker_id):
        step = run["steps"].get(step_id)
        if step is None:
            raise WorkflowError("unknown step: %s" % step_id, "unknown_step")
        if step["status"] == STEP_RUNNING and step["worker_id"] == worker_id:
            return step
        raise LeaseError("step %s lease is not held by worker %s" % (step_id, worker_id))

    def complete(self, tenant, run_id, step_id, worker_id, result=None):
        """Idempotent: repeating the same complete is a no-op."""
        now = self.now()
        with self.store.locked():
            run = self.get_run(tenant, run_id)
            if run["status"] == RUN_CANCELLED:
                raise ConflictError("run %s is cancelled" % run_id, "run_cancelled")
            step = run["steps"].get(step_id)
            if step is None:
                raise WorkflowError("unknown step: %s" % step_id, "unknown_step")
            if step.get("kind") == KIND_APPROVAL:
                raise ConflictError(
                    "step %s is an approval node; use /decision" % step_id, "not_a_task"
                )
            if step["status"] == STEP_SUCCEEDED and step["worker_id"] == worker_id:
                return run
            step = self._require_lease(run, step_id, worker_id)
            if float(step["lease_deadline"]) <= now:
                raise LeaseError("lease for step %s expired" % step_id, "lease_expired")
            step.update(attempt=step["attempt"] + 1, status=STEP_SUCCEEDED, result=result,
                        error=None, finished_at=self._iso(), lease_deadline=None)
            self._event(run, run_id, step_id, "complete", attempt=step["attempt"],
                        worker_id=worker_id, result=result)
            self._open_root_nodes(run)
            run["status"] = _derive_run_status(run)
            if run["status"] == RUN_SUCCEEDED:
                self._event(run, run_id, None, "run_succeeded")
            elif run["status"] == RUN_FAILED:
                # A run with custom trigger rules finishes only when every
                # node is terminal, so the last completion may close it as
                # failed (a sibling branch failed earlier).
                self._event(run, run_id, None, "run_failed")
            run["updated_at"] = self._iso()
            self.store.save_run(run)
            return run

    def fail(self, tenant, run_id, step_id, worker_id, error=None):
        """Count the attempt, retry with backoff, or fail the step and run."""
        now = self.now()
        with self.store.locked():
            run = self.get_run(tenant, run_id)
            if run["status"] == RUN_CANCELLED:
                raise ConflictError("run %s is cancelled" % run_id, "run_cancelled")
            step = run["steps"].get(step_id)
            if step is None:
                raise WorkflowError("unknown step: %s" % step_id, "unknown_step")
            if step.get("kind") == KIND_APPROVAL:
                raise ConflictError(
                    "step %s is an approval node; use /decision" % step_id, "not_a_task"
                )
            step = self._require_lease(run, step_id, worker_id)
            step.update(attempt=step["attempt"] + 1, worker_id=None, lease_deadline=None, error=error)
            self._event(run, run_id, step_id, "fail", attempt=step["attempt"], worker_id=worker_id,
                        error=error)
            if step["attempt"] >= int(step["max_attempts"]):
                step.update(status=STEP_FAILED, finished_at=self._iso(), next_attempt_at=None)
                self._event(run, run_id, step_id, "attempts_exhausted", attempt=step["attempt"],
                            worker_id=worker_id)
                # A terminal failure settles dependents: custom-rule nodes
                # may now unlock (all_done) or skip (all_success/any_success).
                self._open_root_nodes(run)
            else:
                step.update(status=STEP_READY, ready_at=self._iso(),
                            next_attempt_at=self._iso(now + backoff_seconds(
                                step["attempt"], self.backoff_base)))
                self._event(run, run_id, step_id, "retry", attempt=step["attempt"],
                            worker_id=worker_id, next_attempt_at=step["next_attempt_at"])
            run["status"] = _derive_run_status(run)
            if run["status"] == RUN_FAILED:
                self._event(run, run_id, None, "run_failed")
            run["updated_at"] = self._iso()
            self.store.save_run(run)
            return run

    # -- cancellation --------------------------------------------------
    def cancel(self, tenant, run_id, actor):
        """Cancel an unfinished run; a repeat cancel is a no-op.

        Every non-terminal node (``pending``, ``ready``, ``running`` or
        ``waiting``) becomes ``cancelled`` in ``step_order``; already
        ``succeeded`` nodes are left untouched.  Cancelled nodes keep their
        ``attempt``, ``result`` and ``error`` and release their lease
        (``worker_id``, ``lease_deadline`` and ``next_attempt_at`` are
        cleared).  Each cancelled node records one ``cancel`` history event
        carrying the lease holder it had and the cancelling actor, and a
        final run-level ``run_cancelled`` event closes the transition; the
        audit stream follows the same order.  A sleeping run (a future
        ``not_before``) is cancelled without opening its root nodes.

        Cancelling never deletes the run, its workflow, its idempotency
        binding or its history.  A run that is already ``succeeded`` or
        ``failed`` conflicts (``run_finished``); a run that is already
        ``cancelled`` returns the current document without new history,
        audit records or a changed ``updated_at``.
        """
        tenant = normalize_tenant(tenant)
        if not isinstance(actor, str):
            raise WorkflowError("actor must be a string", "bad_actor")
        actor = actor.strip()
        if not actor:
            raise WorkflowError("actor must be a non-empty string", "bad_actor")
        with self.store.locked():
            owner = self.store.run_exists(run_id)
            if owner is None:
                raise WorkflowError("unknown run: %s" % run_id, "unknown_run")
            if owner != tenant:
                raise WorkflowError("run %s belongs to another tenant" % run_id, "cross_tenant")
            run = self.get_run(tenant, run_id)
            if run["status"] == RUN_CANCELLED:
                # Idempotent repeat: the stored document is returned as is.
                return run
            if run["status"] in (RUN_SUCCEEDED, RUN_FAILED):
                raise ConflictError("run %s is already %s" % (run_id, run["status"]),
                                    "run_finished")
            index = run["order_index"]
            for sid in sorted(run["steps"], key=lambda s: index.get(s, 0)):
                step = run["steps"][sid]
                if step["status"] in TERMINAL_STEP_STATES:
                    continue
                holder = step.get("worker_id")
                step.update(status=STEP_CANCELLED, worker_id=None, lease_deadline=None,
                            next_attempt_at=None)
                self._event(run, run_id, sid, "cancel", attempt=step["attempt"],
                            worker_id=holder, actor=actor)
            run["status"] = RUN_CANCELLED
            self._event(run, run_id, None, "run_cancelled", actor=actor)
            run["updated_at"] = self._iso()
            self.store.save_run(run)
            return run

    # -- human decisions -----------------------------------------------
    def decide(self, tenant, run_id, step_id, actor, decision):
        """Record a human approve/reject decision for an approval step.

        Repeating the *same* decision from the *same* actor is idempotent and
        returns the unchanged run; a different actor or the opposite decision
        conflicts with the recorded decision.
        """
        if not isinstance(actor, str) or not actor.strip():
            raise WorkflowError("actor must be a non-empty string", "bad_actor")
        actor = actor.strip()
        if decision not in ("approve", "reject"):
            raise WorkflowError("decision must be 'approve' or 'reject'", "bad_decision")
        with self.store.locked():
            run = self.get_run(tenant, run_id)
            if run["status"] == RUN_CANCELLED:
                raise ConflictError("run %s is cancelled" % run_id, "run_cancelled")
            step = run["steps"].get(step_id)
            if step is None:
                raise WorkflowError("unknown step: %s" % step_id, "unknown_step")
            if step.get("kind") != KIND_APPROVAL:
                raise ConflictError("step %s is not an approval node" % step_id, "not_an_approval")
            recorded = step.get("approval")
            if recorded is not None:
                if recorded["actor"] == actor and recorded["decision"] == decision:
                    return run
                raise ConflictError(
                    "step %s already decided by %s: %s"
                    % (step_id, recorded["actor"], recorded["decision"]),
                    "already_decided",
                )
            if step["status"] != STEP_WAITING:
                raise ConflictError(
                    "step %s is not waiting for a decision" % step_id, "not_waiting"
                )
            event = self._event(run, run_id, step_id, "decision", attempt=0, worker_id=None,
                                actor=actor, decision=decision)
            at = event["at"]
            step["approval"] = {"actor": actor, "decision": decision, "at": at}
            previous = run["status"]
            if decision == "approve":
                step.update(status=STEP_SUCCEEDED, finished_at=at)
            else:
                step.update(status=STEP_FAILED, finished_at=at)
            # Either way the node is terminal now: dependents governed by
            # custom trigger rules may unlock or skip.  All-all_success runs
            # derive the same immediate failure as before on a reject.
            self._open_root_nodes(run, at)
            run["status"] = _derive_run_status(run)
            if run["status"] == RUN_RUNNING and previous == RUN_PENDING:
                self._event(run, run_id, None, "run_started")
            if run["status"] == RUN_SUCCEEDED:
                self._event(run, run_id, None, "run_succeeded")
            elif run["status"] == RUN_FAILED:
                self._event(run, run_id, None, "run_failed")
            run["updated_at"] = at
            self.store.save_run(run)
            return run

    # -- history / replay ----------------------------------------------
    def replay(self, tenant, run_id):
        """Rebuild run state from the run's frozen definition and history.

        Nodes are rebuilt from the normalized DAG snapshotted into the run
        document at creation time, never from the workflow currently stored
        under the run's ``workflow_id``: a later same-name submission may
        replace that workflow, but existing runs keep their original step
        order, node kinds, dependencies, ``max_attempts`` and state-machine
        semantics.  Documents written before snapshots existed reconstruct
        the plan from the definitions and order saved in the run itself.

        The result agrees with the persisted run on every observable field —
        ``run_id``, ``workflow_id``, ``step_order``, run and per-step
        ``status``, ``attempt``, ``worker_id``, ``lease_deadline``,
        ``next_attempt_at``, ``ready_at``, ``started_at``, ``finished_at``,
        ``result``, ``error`` and ``approval`` — and the append-only history
        is the sole source of transitions, so replaying again, including
        after a restart, yields the identical document.
        """
        owner = self.store.run_exists(run_id)
        if owner is None:
            raise WorkflowError("unknown run: %s" % run_id, "unknown_run")
        if owner != tenant:
            raise WorkflowError("run %s belongs to another tenant" % run_id, "cross_tenant")
        stored = self.store.load_run(tenant, run_id)
        plan = run_plan(stored)
        rebuilt = new_run(tenant, stored["workflow_id"], run_id, stored.get("params"), plan,
                          stored["created_at"],
                          max_parallelism=stored.get("max_parallelism"),
                          idempotency_key=stored.get("idempotency_key"),
                          not_before=stored.get("not_before"),
                          schedule_id=stored.get("schedule_id"),
                          scheduled_at=stored.get("scheduled_at"))
        # The fresh document must carry exactly the frozen snapshot and
        # ordering of the stored run (new_run fills them from the same plan
        # already, but align them defensively for reconstructed old plans).
        rebuilt["plan"] = copy.deepcopy(plan)
        rebuilt["step_order"] = list(plan["order"])
        rebuilt["order_index"] = {sid: i for i, sid in enumerate(plan["order"])}
        steps = rebuilt["steps"]
        for event in stored["history"]:
            sid, etype, at = event.get("step_id"), event.get("type"), event.get("at")
            attempt = event.get("attempt")
            if sid is None:
                # Run-level markers (run_created, run_started, run_succeeded,
                # run_failed, run_cancelled) need no replay action: the run
                # status is derived from the rebuilt nodes at the end,
                # exactly as every live transition derives it before
                # persisting.
                continue
            step = steps.get(sid)
            if step is None:
                # The frozen definition has no node for this event: a node
                # introduced by a later same-name workflow must not appear
                # here, and old events can never reference a removed node.
                continue
            if etype == "ready":
                step.update(status=STEP_READY, ready_at=at)
            elif etype == "waiting":
                step.update(status=STEP_WAITING)
            elif etype == "skipped":
                # Mirrors the settle pass: the node never ran, keeps its
                # attempt and holds no lease fields.
                step.update(status=STEP_SKIPPED)
            elif etype == "claim":
                step.update(status=STEP_RUNNING, worker_id=event.get("worker_id"),
                            started_at=at, lease_deadline=event.get("lease_deadline"),
                            next_attempt_at=None)
            elif etype == "heartbeat":
                step["lease_deadline"] = event.get("lease_deadline")
            elif etype == "takeover":
                # Mirrors _expire_leases: the node is re-queued with a fresh
                # ready_at and no holder; started_at from the lost lease is
                # left in place, exactly as the live transition leaves it.
                step.update(status=STEP_READY, worker_id=None, lease_deadline=None,
                            ready_at=at)
            elif etype == "complete":
                # Mirrors complete(): the successful node keeps the worker
                # that completed it and clears any prior failure error.
                step.update(status=STEP_SUCCEEDED, result=event.get("result"), error=None,
                            finished_at=at, lease_deadline=None,
                            worker_id=event.get("worker_id"),
                            attempt=step["attempt"] if attempt is None else attempt)
            elif etype == "decision":
                approved = event.get("decision") == "approve"
                step.update(status=STEP_SUCCEEDED if approved else STEP_FAILED,
                            finished_at=at,
                            approval={"actor": event.get("actor"),
                                      "decision": event.get("decision"), "at": at})
            elif etype == "fail":
                step.update(error=event.get("error"), worker_id=None, lease_deadline=None,
                            attempt=step["attempt"] if attempt is None else attempt)
            elif etype == "retry":
                step.update(status=STEP_READY, ready_at=at,
                            next_attempt_at=event.get("next_attempt_at"))
            elif etype == "attempts_exhausted":
                step.update(status=STEP_FAILED, finished_at=at, next_attempt_at=None)
            elif etype == "cancel":
                # Mirrors cancel(): the node keeps attempt/result/error and
                # releases its lease; ready_at/started_at stay as recorded.
                step.update(status=STEP_CANCELLED, worker_id=None, lease_deadline=None,
                            next_attempt_at=None)
        # Every live write path derives the run status from its nodes, so
        # rebuilding from the same nodes yields the same status — including
        # the pending/running boundary (a run with only ready/waiting nodes
        # and no claim is still pending; a retry-queued run has returned to
        # pending even though a run_started event exists).
        rebuilt["status"] = _derive_run_status(rebuilt)
        rebuilt["updated_at"] = stored.get("updated_at")
        rebuilt["history"] = copy.deepcopy(stored["history"])
        return rebuilt

"""Standard library HTTP API for flowd."""

import json
import re
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, unquote, urlparse

from .model import WorkflowError
from .scheduler import ConflictError, LeaseError

MAX_BODY = 1 << 20
STATUS_FOR_CODE = {"unknown_run": 404, "unknown_workflow": 404, "unknown_step": 404,
                   "unknown_worker": 404, "unknown_schedule": 404,
                   "schedule_exists": 409, "cross_tenant": 403}
DECISIONS = ("approve", "reject")


class _Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "flowd/0.1"

    def log_message(self, fmt, *args):  # keep the console quiet
        pass

    # -- plumbing ------------------------------------------------------
    def _send(self, code, raw=b""):
        self.send_response(code)
        if code != 204:
            self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        if raw:
            self.wfile.write(raw)

    def _json(self, code, payload):
        self._send(code, json.dumps(payload, ensure_ascii=True, sort_keys=True).encode("utf-8"))

    def _error(self, code, message):
        self._json(code, {"error": message})

    def _body(self):
        length = int(self.headers.get("Content-Length") or 0)
        if length <= 0:
            return {}
        if length > MAX_BODY:
            raise WorkflowError("request body too large", "body_too_large")
        try:
            payload = json.loads(self.rfile.read(length).decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            raise WorkflowError("request body must be valid JSON", "bad_json")
        if not isinstance(payload, dict):
            raise WorkflowError("request body must be a JSON object", "bad_json")
        return payload

    def _tenant(self, query, body=None):
        tenant = (body or {}).get("tenant") or (query.get("tenant") or [None])[0]
        if not tenant:
            raise WorkflowError("tenant is required", "bad_tenant")
        return tenant
    # -- verbs ---------------------------------------------------------
    def do_GET(self):
        self._dispatch("GET")

    def do_POST(self):
        self._dispatch("POST")

    def _dispatch(self, method):
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"
        try:
            self._route(method, path, parse_qs(parsed.query), parsed.query)
        except LeaseError as exc:
            self._error(409, exc.message)
        except ConflictError as exc:
            self._error(409, exc.message)
        except WorkflowError as exc:
            self._error(STATUS_FOR_CODE.get(exc.code, 400), exc.message)
        except Exception as exc:  # pragma: no cover - defensive
            self._error(500, "internal error: %s" % exc)

    def _route(self, method, path, query, raw_query=""):
        body = {}
        if method == "GET":
            if path == "/healthz":
                return self._json(200, {"ok": True})
            if path == "/v1/runs":
                return self._list_runs(query)
            if path == "/v1/schedules":
                return self._list_schedules(query)
            if path == "/v1/workers":
                return self._list_workers(query)
            if path == "/v1/quotas":
                return self._get_quota(query)
            if path == "/v1/audit":
                # Blank values count as "provided" here: an empty tenant,
                # action or run_id is a 400, not a missing parameter.
                return self._list_audit(parse_qs(raw_query, keep_blank_values=True))
        elif method == "POST":
            if path == "/v1/tasks/claim":
                return self._claim_any_task(self._body())
            if path == "/v1/workers/register":
                return self._register_worker(self._body())
            worker_beat = re.fullmatch(r"/v1/workers/([^/]+)/heartbeat", path)
            if worker_beat:
                return self._worker_heartbeat(unquote(worker_beat.group(1)), self._body())
            if path == "/v1/workflows":
                body = self._body()
                tenant = self._tenant({}, body)
                plan = self.scheduler.submit(tenant, body.get("workflow_id"), body.get("steps"))
                return self._json(201, dict(plan, tenant=tenant))
            if path == "/v1/runs":
                body = self._body()
                run = self.scheduler.start_run(self._tenant({}, body), body.get("workflow_id"),
                                               body.get("run_id"), body.get("params"),
                                               body.get("max_parallelism"),
                                               body.get("idempotency_key"),
                                               body.get("not_before"))
                return self._json(201, _run_view(run))
            if path == "/v1/schedules":
                return self._create_schedule(self._body())
            if path == "/v1/quotas":
                return self._set_quota(self._body())
            schedule_dispatch = re.fullmatch(r"/v1/schedules/([^/]+)/dispatch", path)
            if schedule_dispatch:
                return self._dispatch_schedule(unquote(schedule_dispatch.group(1)), self._body())
            action = re.fullmatch(r"/v1/runs/([^/]+)/(claim|complete|fail|decision|heartbeat|cancel)", path)
            if action:
                if action.group(2) == "decision":
                    return self._decision(action.group(1), self._body())
                if action.group(2) == "heartbeat":
                    return self._heartbeat(action.group(1), self._body())
                if action.group(2) == "cancel":
                    return self._cancel(action.group(1), self._body())
                return self._step_action(action.group(1), action.group(2), self._body())
        solo = re.fullmatch(r"/v1/runs/([^/]+)", path)
        if method == "GET" and solo:
            return self._get_run(query, solo.group(1))
        return self._error(404, "no route for %s %s" % (method, path))

    # -- handlers ------------------------------------------------------
    def _get_run(self, query, run_id):
        tenant = self._tenant(query)
        owner = self.scheduler.store.run_exists(run_id)
        if owner is not None and owner != tenant:
            raise WorkflowError("run %s belongs to another tenant" % run_id, "cross_tenant")
        return self._json(200, _run_view(self.scheduler.get_run(tenant, run_id)))

    def _list_runs(self, query):
        tenant = self._tenant(query)
        items, next_after = self.scheduler.list_runs(
            tenant,
            status=(query.get("status") or [None])[0],
            limit=int((query.get("limit") or ["50"])[0]),
            after=(query.get("after") or [None])[0],
        )
        return self._json(200, {"tenant": tenant, "items": [_run_view(r) for r in items],
                                "next_after": next_after})

    # -- audit stream ----------------------------------------------------
    @staticmethod
    def _query_int(query, name, default, code):
        raw = (query.get(name) or [None])[0]
        if raw is None:
            return default
        try:
            return int(raw, 10)
        except ValueError:
            raise WorkflowError("%s must be an integer" % name, code)

    def _list_audit(self, query):
        tenant = (query.get("tenant") or [None])[0]
        if not isinstance(tenant, str) or not tenant.strip():
            raise WorkflowError("tenant must be a non-empty string", "bad_tenant")
        limit = self._query_int(query, "limit", 100, "bad_limit")
        if not 1 <= limit <= 1000:
            raise WorkflowError("limit must be an integer between 1 and 1000", "bad_limit")
        after = self._query_int(query, "after", 0, "bad_after")
        if after < 0:
            raise WorkflowError("after must be a non-negative integer", "bad_after")
        action = (query.get("action") or [None])[0]
        if action is not None and not action.strip():
            raise WorkflowError("action must be a non-empty string", "bad_action")
        run_id = (query.get("run_id") or [None])[0]
        if run_id is not None and not run_id.strip():
            raise WorkflowError("run_id must be a non-empty string", "bad_run_id")
        items, next_after = self.scheduler.list_audit(
            tenant, action=action, run_id=run_id, limit=limit, after=after)
        return self._json(200, {"tenant": tenant.strip(), "items": items,
                                "next_after": next_after})

    # -- periodic schedules -------------------------------------------
    def _create_schedule(self, body):
        record = self.scheduler.create_schedule(
            self._tenant({}, body), body.get("schedule_id"), body.get("workflow_id"),
            body.get("interval_seconds"), body.get("first_at"), body.get("params"),
            body.get("max_parallelism"),
        )
        return self._json(201, _schedule_view(record))

    def _list_schedules(self, query):
        tenant = self._tenant(query)
        return self._json(200, {"tenant": tenant,
                                "items": [_schedule_view(r)
                                          for r in self.scheduler.list_schedules(tenant)]})

    def _dispatch_schedule(self, schedule_id, body):
        run, scheduled_at = self.scheduler.dispatch_schedule(self._tenant({}, body),
                                                              schedule_id)
        if run is None:
            return self._send(204)
        return self._json(201, _run_view(run, scheduled_at=scheduled_at))

    # -- worker registry -----------------------------------------------
    def _worker_lease(self, body):
        """Extract lease_seconds: omitted defaults to 30, explicit null is 400."""
        if "lease_seconds" not in body:
            return 30
        lease = body["lease_seconds"]
        if lease is None:
            raise WorkflowError("lease_seconds must be a positive number", "bad_lease")
        return lease

    def _register_worker(self, body):
        record, created = self.scheduler.register_worker(
            body.get("tenant"), body.get("worker_id"), self._worker_lease(body)
        )
        return self._json(201 if created else 200, record)

    def _worker_heartbeat(self, worker_id, body):
        record = self.scheduler.heartbeat_worker(
            body.get("tenant"), worker_id, self._worker_lease(body)
        )
        return self._json(200, record)

    def _list_workers(self, query):
        tenant = self._tenant(query)
        return self._json(200, {"tenant": tenant,
                                "items": self.scheduler.list_workers(tenant)})

    # -- tenant concurrency quota ---------------------------------------
    def _set_quota(self, body):
        """Create or update the tenant quota: 201 first write, 200 update."""
        record, created = self.scheduler.set_quota(
            body.get("tenant"), body.get("max_parallelism"))
        return self._json(201 if created else 200, _quota_view(record))

    def _get_quota(self, query):
        tenant = (query.get("tenant") or [None])[0]
        return self._json(200, _quota_view(self.scheduler.get_quota(tenant)))

    def _claim_any_task(self, body):
        """Tenant-wide fair claim: 200 {"run_id","step"} or 204 when idle."""
        lease = body.get("lease_seconds", 30)
        if lease is None:
            raise WorkflowError("lease_seconds must be a positive number", "bad_lease")
        result = self.scheduler.claim_fair(body.get("tenant"), body.get("worker_id"), lease)
        if result is None:
            return self._send(204)
        run_id, step = result
        return self._json(200, {"run_id": run_id, "step": _step_view(step)})

    def _step_action(self, run_id, action, body):
        tenant, worker_id = self._tenant({}, body), body.get("worker_id")
        if action == "claim":
            step = self.scheduler.claim(tenant, run_id, worker_id, body.get("lease_seconds", 30))
            return self._send(204) if step is None else self._json(200, {"step": _step_view(step)})
        if action == "complete":
            run = self.scheduler.complete(tenant, run_id, body.get("step_id"), worker_id,
                                          body.get("result"))
        else:
            run = self.scheduler.fail(tenant, run_id, body.get("step_id"), worker_id,
                                      body.get("error"))
        return self._json(200, _run_view(run))

    def _heartbeat(self, run_id, body):
        """Renew a lease; strict field validation, anything bad is a 400."""
        for name in ("tenant", "step_id", "worker_id"):
            value = body.get(name)
            if not isinstance(value, str) or not value.strip():
                raise WorkflowError("%s must be a non-empty string" % name, "bad_%s" % name)
        run = self.scheduler.heartbeat(body["tenant"], run_id, body["step_id"],
                                       body["worker_id"], body.get("lease_seconds", 30))
        return self._json(200, _run_view(run))

    def _cancel(self, run_id, body):
        """Cancel an unfinished run; strict tenant/actor validation."""
        tenant = body.get("tenant")
        if not isinstance(tenant, str) or not tenant.strip():
            raise WorkflowError("tenant must be a non-empty string", "bad_tenant")
        actor = body.get("actor")
        if not isinstance(actor, str) or not actor.strip():
            raise WorkflowError("actor must be a non-empty string", "bad_actor")
        run = self.scheduler.cancel(tenant.strip(), run_id, actor.strip())
        return self._json(200, _run_view(run))

    def _decision(self, run_id, body):
        """Validate strictly; any missing/blank/wrong-type field is a 400."""
        fields = {}
        for name in ("tenant", "step_id", "actor"):
            value = body.get(name)
            if not isinstance(value, str) or not value.strip():
                raise WorkflowError("%s must be a non-empty string" % name, "bad_%s" % name)
            fields[name] = value.strip()
        decision = body.get("decision")
        if decision not in DECISIONS:
            raise WorkflowError("decision must be one of %s" % ", ".join(DECISIONS),
                                "bad_decision")
        tenant = fields["tenant"]
        owner = self.scheduler.store.run_exists(run_id)
        if owner is not None and owner != tenant:
            raise WorkflowError("run %s belongs to another tenant" % run_id, "cross_tenant")
        run = self.scheduler.decide(tenant, run_id, fields["step_id"], fields["actor"], decision)
        return self._json(200, _run_view(run))


def _step_view(step):
    return {"id": step["id"], "kind": step.get("kind", "task"), "status": step["status"],
            "attempt": step["attempt"],
            "max_attempts": step["max_attempts"], "depends_on": list(step["depends_on"]),
            "trigger_rule": step.get("trigger_rule", "all_success"),
            "worker_id": step["worker_id"], "lease_deadline": step["lease_deadline"],
            "next_attempt_at": step["next_attempt_at"], "result": step.get("result"),
            "error": step.get("error"), "approval": step.get("approval")}


def _quota_view(record):
    return {"tenant": record["tenant"],
            "max_parallelism": record.get("max_parallelism"),
            "updated_at": record.get("updated_at")}


def _schedule_view(record):
    return {"tenant": record["tenant"], "schedule_id": record["schedule_id"],
            "workflow_id": record["workflow_id"],
            "interval_seconds": record["interval_seconds"],
            "first_at": record.get("first_at"), "next_at": record.get("next_at"),
            "params": record.get("params") or {},
            "max_parallelism": record.get("max_parallelism"),
            "created_at": record.get("created_at"), "updated_at": record.get("updated_at")}


def _run_view(run, scheduled_at=None):
    if scheduled_at is None:
        scheduled_at = run.get("scheduled_at")
    return {"tenant": run["tenant"], "run_id": run["run_id"], "workflow_id": run["workflow_id"],
            "status": run["status"], "params": run.get("params") or {},
            "max_parallelism": run.get("max_parallelism"),
            "idempotency_key": run.get("idempotency_key"),
            "not_before": run.get("not_before"),
            "schedule_id": run.get("schedule_id"),
            "scheduled_at": scheduled_at,
            "created_at": run.get("created_at"), "updated_at": run.get("updated_at"),
            "steps": [_step_view(run["steps"][sid]) for sid in run["step_order"]],
            "history_length": len(run.get("history") or [])}


def create_server(store, host="127.0.0.1", port=8080, scheduler=None):
    """Build (but do not start) a ThreadingHTTPServer bound to ``host:port``."""
    if scheduler is None:
        from .scheduler import Scheduler

        scheduler = Scheduler(store)
    return ThreadingHTTPServer((host, int(port)),
                               type("FlowdHandler", (_Handler,), {"scheduler": scheduler}))

